import{_ as t}from"./chunks/d0717da8ef2969d46fc5.CVzw3ADq.js";import{_ as r,C as o,o as l,c as i,j as e,a as n,E as h,a6 as s}from"./chunks/framework.CnPv4DE1.js";const g=JSON.parse('{"title":"对你现在的生活感到愤怒（从而超越99%的人）","description":"","frontmatter":{"title":"对你现在的生活感到愤怒（从而超越99%的人）","originalTitle":"Get Mad At Where You Are In Life (To Get Ahead Of 99% Of People)","date":"2023-06-03","originalUrl":"https://thedankoe.com/letters/get-mad-at-where-you-are-in-life-to-get-ahead-of-99-of-people/","minutes":11,"sourceHash":"79c2a7303ef7b606ae82e2a296b9213ebf7c8b2e0ec73c7f4a231795fa094608","translation":"AI-assisted, block-aligned; not official","head":[["link",{"rel":"canonical","href":"https://thedankoe.com/letters/get-mad-at-where-you-are-in-life-to-get-ahead-of-99-of-people/"}]]},"headers":[],"relativePath":"letters/get-mad-at-where-you-are-in-life-to-get-ahead-of-99-of-people.md","filePath":"letters/get-mad-at-where-you-are-in-life-to-get-ahead-of-99-of-people.md"}'),d={name:"letters/get-mad-at-where-you-are-in-life-to-get-ahead-of-99-of-people.md"};function m(f,p,c,u,b,_){const a=o("ArticleMeta");return l(),i("div",null,[p[0]||(p[0]=e("h1",{id:"对你现在的生活感到愤怒-从而超越99-的人",tabindex:"-1"},[n("对你现在的生活感到愤怒（从而超越99%的人） "),e("a",{class:"header-anchor",href:"#对你现在的生活感到愤怒-从而超越99-的人","aria-label":'Permalink to "对你现在的生活感到愤怒（从而超越99%的人）"'},"​")],-1)),h(a),p[1]||(p[1]=s('<p><a href="https://www.youtube.com/embed/RV9rlD6rHRo?feature=oembed" target="_blank" rel="noreferrer">观看原文视频</a></p><p>我生命中最美好的时期，总是出现在我对自己毫无进展感到绝对厌倦的一段时期之后。</p><p>我开始理解“缓解”与“治愈”之间的区别。</p><p>缓解的感觉很好。</p><p>它以廉价的快乐、无脑的娱乐和处方药的形式出现。</p><p>人类害怕改变。</p><p>所以我们死死抓住外部世界呈现出来的安全感幻觉。</p><p>那些建议。</p><p>那些超越性本身的色情内容。</p><p>那些对美好生活的承诺。</p><p>那些极具说服力的营销话术。</p><p>那些可能提供安全感，但并非源自你自身理解的事物。</p><p>而治愈是痛苦的。</p><p>它的表现形式是你对病态感到极度厌倦，直到你完成了一个闭环。</p><p>我所说的闭环，是指认知上一次彻底而激进的反转。</p><p>想象一条从黑到白渐变的线，中间有各种深浅不一的灰色。</p><p>然后，把这条线的两端连在一起，让黑色和白色相碰。</p><p>我们可以在日常生活中看到这种现实模式。</p><p>一个人愚蠢到了极点，反而变得富有洞察力。</p><p>一套极其土气的穿搭，反而变得很时尚。</p><p>一个极其不好笑的笑话，反而变得搞笑了。</p><p>一个被困至极的无神论者，反而变成了信徒。</p><p>或者，一个人对自己感到极度厌倦，反而变成了一个全新的人。</p><h2 id="人格孕育行动" tabindex="-1">人格孕育行动 <a class="header-anchor" href="#人格孕育行动" aria-label="Permalink to &quot;人格孕育行动&quot;">​</a></h2><p><em>身份限制了视角。</em></p><p>它提供了一个边界，这样你的思想就不会跌入未知的领地，从而威胁到你的整个存在。</p><p><em>视角影响认知。</em></p><p>任何特定情境中包含的信息都多到显意识无法处理（我们每秒大概只能处理50比特的信息）。</p><p>你随着时间培养的身份或人格，会限制你处理哪些信息，而这些信息正是你当前视角所能接触到的。</p><p>基于这些信息，你会做出与其他所有人都不一样的解读。</p><p>我可以让你想象一只“鸟”，你脑海中浮现的画面，会与这个星球上的任何其他人都不同。</p><p>有些人会想到北美红雀，另一些人会想到冠蓝鸦，它们都在你脑海中用模糊的线条勾勒出画面。然而，<em>鸟到底是什么</em>的潜在本质，依然是不变的。</p><p>对于像“上帝”这样的概念也是如此。人们为了不同的解读和“证据”而发动战争，但实际上，这个概念所指向的<em>体验</em>或<em>本质</em>是一样的，并且它就摆在你面前，只是模式化的思维阻碍了你看透表面。</p><p>既然说到了“上帝”这么敏感的话题，那我们顺便结合一下“基督意识”（Christ Consciousness）的例子。</p><p>基督的身份扩展到了<em>万物</em>，因此他的视角也随之扩展了。</p><p>他能全盘感知事物，看清它们的本来面目。</p><p>我来这里不是要给你上什么宗教、意识形态或教条的课，因为那跟我真正想表达的东西完全背道而驰。<em>小心你僵化的身份如何影响你对这些文字的理解（因为我也曾是那个盲目反刍“事实”的傻x，对自己没有体验过的东西指手画脚，好像它绝对不可能存在一样）。</em></p><p>我不盲从任何单一的视角，而是试图将所有视角中的真理整合进我的世界观中。在这方面我远谈不上完美，但很难否认的是，在每一种文化信仰体系中，大家指向的其实都是同一个东西。当你在研究不同视角时，因识别出规律而获得的那种充满意义的多巴胺，正标志着你正走在正确的方向上。</p><p><em>认知影响你在世界中的行动方式。</em></p><p>那些严重受制于宗教、营养学、商业或政治意识形态的人，几乎总是会按照那种智力建构赋予他们的目标去行动。</p><p>而那些寻求敞开心扉以获得觉知和理解的人，则能做出有助于实现他们理想未来的决定。</p><p>行动总是指向一个目标的。总是如此。</p><p>你的身份里已经内置了目标。</p><p>问题在于，这些目标到底是你自己生成的，还是外部世界强加给你的。</p><p>一个毫无质疑地全盘接受父母信仰的政治盲从者，将会为了政党指派的目标而行动。</p><p>一个凭借热情和自学成才的健美运动员，会生成他们自己的目标，并让他们的营养、生活方式和训练与该目标保持一致——否则他们就会经历痛苦。这种痛苦并不坏，反而是一个指向更好状态的有用指南针。</p><p>人格创造行动，行动又强化了人格。</p><p>如果你想改变自己，去挑战你的信念吧。</p><p>让你的行动随着<em>时间</em>（不是一天、一周甚至一个月，而是一生）跟上步伐。</p><p>通过这样做，你会创造一个减少了非自愿痛苦的人生。</p><h2 id="故事中最有趣的部分" tabindex="-1">故事中最有趣的部分 <a class="header-anchor" href="#故事中最有趣的部分" aria-label="Permalink to &quot;故事中最有趣的部分&quot;">​</a></h2><p>大多数人没有意识到，生活<em>本身就是</em>故事。</p><p>故事是宇宙规律的象征。</p><p>你可以在建筑、音乐、万物的创造、经文、系统、环境、经济学以及你的人生中注意到这些规律。</p><p>我们就是这样理解这个世界的。</p><p>大脑通过概念、故事、隐喻和象征来解读世界。</p><p>要理解一样东西，我们必须在潜意识里理解与它相连的一切。</p><p>没有手，杯子就毫无意义。</p><p>没有力或质量，引力就讲不通。</p><p>脱离了当下的社会和文化状态，你的人生也将无法解释。</p><p>你所知道的一切，都不过是一层故事，包含着数十亿个开/关的信息位，它们被拼凑在一起以适应你当前的理解水平。</p><p>故事赋予生活意义。</p><p>你的身份就是你讲给自己听的故事。</p><p>如果不把它带入意识层面，你就会在自动驾驶模式下活出那个故事。</p><p>在你人生这本书中，眼下正在你面前展开的是哪个词、哪句话、哪个段落、哪个小节、哪个章节？</p><p>现在，我们必须引入两极性（polarity）的话题，来深化我们对意义的理解。</p><p>简而言之，任何事物都无法脱离其对立面而存在。</p><p>没有悲伤作为参照物，幸福就不可能存在。</p><p>就像没有手就没有杯子。</p><p>或者没有苦难就没有生活。</p><p>关于最后一点，故事的高潮往往是最令人难忘的。</p><p>当战斗达到顶峰的时候。</p><p>当你不确定未来会怎样的时候。</p><p>当那个象征性的反派眼看就要获胜，而英雄却最终逆转取胜的时候。</p><p>如果你的人生没有低谷，它就会失去所有的意义。</p><p>它会变得扁平。乏味。线性。死气沉沉。机械化。像机器人一样。不动脑子。平庸至极。</p><p>生活就是一场秩序与混乱之间的舞蹈。</p><p>推与拉。阴与阳。男性与女性。</p><p>从个人到社会，再到文化，直至宇宙。</p><p>如果你从不接受战斗，从不失去阵地，也从不朝新的方向推进，你就永远无法达到新的高度、新的视角或新的意识水平。</p><h2 id="情绪转化" tabindex="-1">情绪转化 <a class="header-anchor" href="#情绪转化" aria-label="Permalink to &quot;情绪转化&quot;">​</a></h2><blockquote><p>Transmutation (名词，转化)：转变成另一种形式的动作或状态。</p></blockquote><p>我右前臂上有一个纹身。</p><p>一条衔尾蛇（ouroboros）。</p><p>一个炼金术的象征。</p><p>它的图案是一条咬着自己尾巴的蛇，呈无限大符号的形状。</p><p>这是一个提醒：创造必然要求毁灭，两者缺一不可。</p><p>它指向等价交换法则：为了得到任何东西，你必须牺牲同等或更大价值的东西。</p><p>商业的转化是将创造变成金钱。</p><p>情绪的转化则是将你的情绪状态变成更强大的力量的行为。</p><p>就像利用愤怒这种强烈的东西，来推动你走向美好的事物。</p><p>当然，这很快可能会变得危险。</p><p>情绪转化<em>不是</em>成为那种情绪的奴隶，任由它支配你的行动。</p><p>我们要像精神上的太极大师一样，捕捉、感受并引导我们的负面情绪。我们要去利用它，而不是被它利用。</p><p>为了给自己创造一个更好的生活，情绪能量是燃料，而刻意的努力是载体。</p><p>当你跌入人生的低谷时，你会直接接触到一种绝大多数人都会浪费的强大（但短暂的）燃料源。那个低谷是一条快速连接神性的通道。</p><p>当属于你的这一刻到来时，别浪费它。</p><h2 id="引导去建设" tabindex="-1">引导去建设 <a class="header-anchor" href="#引导去建设" aria-label="Permalink to &quot;引导去建设&quot;">​</a></h2><p><img src="'+t+'" alt=""></p><p>当你跌入那个低谷时，你需要一些实质性的东西，来引导这股新发现的（而且极其强大的）能量。</p><p>一个与你愿景一致的项目。</p><p>也就是你所陷入低谷的对立面。</p><p>从对负面事物的觉察中，你可以轻易识别出你在生活中不想要的东西。由此，你就能具象化一个值得为之奋斗的美好未来。</p><p>如果你跌入了财务低谷，也许是时候开始创业或者找份新工作了。</p><p>如果你刚经历分手，也许是时候把重心转移到健身房里的健康和个人发展上了。</p><p>我认识的大多数成功人士，都是出于对生活中某种境况的纯粹憎恨而开启他们的旅程的。</p><p>他们痛恨通勤上班。</p><p>他们痛恨每周5天都要穿着那身憋屈的职业装。</p><p>他们痛恨自己任由某段感情苟延残喘，或者痛恨自己对那段想要挽留的感情来说“不够好”。</p><p>当他们感受到那种情绪，并放下死死抓住不放的欲望时，一种新的潜能展现了出来，行动也变得毫无阻力。</p><p>大多数人认为“恨”不该存在，其实它只不过是爱的受阻而已。而如果那个阻碍不被移除，恨意就会附着其上并无休止地蔓延。</p><p>好了，这就是我通过直接经验得出的哲学，这也是你们中许多人阅读这些信件的原因：</p><p>我相信，全能型创业是任何男女的元载体（meta vessel），它能够将生活中的混乱，与那种自我生成、目标导向之建设的阳刚追求平衡起来。</p><p>如果这听起来不太好懂，那让我来解释一下当下的创业环境：</p><h3 id="_1-人人都是创业者。" tabindex="-1">1) 人人都是创业者。 <a class="header-anchor" href="#_1-人人都是创业者。" aria-label="Permalink to &quot;1) 人人都是创业者。&quot;">​</a></h3><p>几个世纪前，每个人都在他们的部落或社区中履行着自己的使命。</p><p>他们获取技能和培养兴趣，以适应作为他们社区的那个“市场”。</p><h3 id="_2-社交媒体不仅是一个app-它是一个新社会。" tabindex="-1">2) 社交媒体不仅是一个App，它是一个新社会。 <a class="header-anchor" href="#_2-社交媒体不仅是一个app-它是一个新社会。" aria-label="Permalink to &quot;2) 社交媒体不仅是一个App，它是一个新社会。&quot;">​</a></h3><p>人们至今仍未意识到社交媒体有多么具有革命性。</p><p>它是我们学习的地方（学校）。</p><p>它是我们招聘的地方（职场）。</p><p>它是我们教学的地方（商业）。</p><p>它是我们相遇的地方（社交）。</p><p>此时此刻，我们就生活在这个虚拟世界中。如果没有我们已经拥有的这个社会主心骨，虚拟现实就不可能存在。</p><p>忽视社交媒体，就是在忽视一条通往你最大潜能的进化之路。</p><h3 id="_3-我们通过解决问题-一路走到了-做你热爱的事-。" tabindex="-1">3) 我们通过解决问题，一路走到了“做你热爱的事”。 <a class="header-anchor" href="#_3-我们通过解决问题-一路走到了-做你热爱的事-。" aria-label="Permalink to &quot;3) 我们通过解决问题，一路走到了“做你热爱的事”。&quot;">​</a></h3><p>进化就是解决各种大小问题的过程。</p><p>除非我们将时间跨度拉长到十多年去反思，否则我们根本注意不到这一点。</p><p>人类的一种内在驱动力，就是去追随你的好奇心，拥抱你的存在本真。</p><p>在这个社会里，没有钱你干不了这事（虽然只是在某种程度上，但这是个硬现实）。因此，利用现代技术作为杠杆，通过做自己享受的事情来赚取收入，就成了一个人的毕生事业。</p><p>要做到这一点，你需要将你的个人兴趣与社交媒体技能（理解社会）、写作、演讲、营销和销售结合起来。</p><p>我在 <a href="/letters/the-1-million-dollar-skill-stack-learn-in-this-order">价值百万美元的技能栈</a> 中探讨过这个话题。</p><h3 id="_4-你就是最赚钱的细分领域。" tabindex="-1">4) 你就是最赚钱的细分领域。 <a class="header-anchor" href="#_4-你就是最赚钱的细分领域。" aria-label="Permalink to &quot;4) 你就是最赚钱的细分领域。&quot;">​</a></h3><p>人生的意义是什么？</p><p>这是一个极具深意的问题，但我认为最合理的答案是：提升集体意识。</p><p>去帮助他人解决他们的问题，这样我们就能超越肤浅的表象，顺应现实的本来面目去生活。</p><p>你生活中的问题包括心理、身体、财务和灵性层面。</p><p>对任何人来说都是如此。</p><p>为了集体的成长，这些都是我们每个人必须去解决的问题。</p><p>作为一个人类整体，我们的强度取决于最薄弱的一环，而这最薄弱的一环往往是平庸、盲目且具有破坏性的。因此，这就是为什么为了意识的觉醒，你必须学习营销和说服。你不是在强行推销你的世界观，你只是在阐述它，并让它顺其自然地发挥作用。</p><p><em>喂饱饥饿的人。</em></p><p>那些吃饱的人最终也会再次感到饥饿。</p><p>当你解决了自己的问题，这就意味着你可以将解决方案传递下去。</p><p>这个解决方案，既是你在社交媒体上获得读者的方式（通过内容），也是你销售每次购买都在拯救世界的产品的方式（<a href="/letters/the-new-wave-of-micro-businesses-monetize-your-knowledge">通过教育</a>）。</p><p>如果你不知道从哪里开始，<a href="https://2hourwriter.com/" target="_blank" rel="noreferrer">试试 2 Hour Writer</a>。</p><h3 id="_5-创作者-不是一份工作-而是一种全新的生活方式。" tabindex="-1">5) “创作者”不是一份工作，而是一种全新的生活方式。 <a class="header-anchor" href="#_5-创作者-不是一份工作-而是一种全新的生活方式。" aria-label="Permalink to &quot;5) “创作者”不是一份工作，而是一种全新的生活方式。&quot;">​</a></h3><p>不管你是否相信某种更高的力量、底层的形而上学结构，或是对造物主（Creator）有任何解释——你都很难否认，创造的行为是纯粹的狂喜，而这是一个信号，告诉你应该更频繁地去创造。</p><p>当你学习、剖析、重新联结并传授时，你就是在施展大脑的创造能力，用阿诺德（Arnold）的智慧之语来说：</p><blockquote><p>对我来说，肌肉充血的泵感就像和美丽的女人做爱并高潮。你懂吗？那种感觉太棒了。我感觉我一直都在高潮，你懂吧！</p></blockquote><p>创造力是大脑的健美。创造是精神的性爱。</p><p>如果每个人都顺应自己作为创作者的天性，那么饱和状态是很难存在的。</p><p>你的故事，或者你的身份（你在创作者圈子中展示出的那一面），与任何其他人相比都截然不同——即使你们追求的是像“赚更多钱”这样同样的高维度目标。</p><p>你一生中可以处理 1280 亿比特的意识信息。</p><p>那就是你的潜能。</p><p>在任何特定时刻，你要么在分心中浪费这种潜能，要么就在利用它来打磨一个具有自觉意识的角色，并借此为人类做出贡献。</p><p>去深入感受你所处的境遇。</p><p>将那股能量转化为朝向某个目标前进的动力。</p><p>获取实现该目标所需的技能。</p><p>追随你的好奇心，以避免落入既定指令的死板机械性之中。</p><p>用你的知识、项目和解决方案去交换注意力和收入。</p><p>利用你自我反思的意识，找出你能力中的差距并加以弥补。</p><p>你拥有资源。</p><p>这需要时间。甚至需要好几年。</p><p>你可能不会现在就开始，这没关系。</p><p>以你目前的意识水平，这封信对你来说可能还无法理解。</p><p>根据你自身的经验水平，在现实中继续向前推进。</p><p>去寻求对宏观大局的理解。</p><p>不要被困在技术细节里。</p><p>享受你周末剩下的时光。</p><p>– Dan Koe</p><hr><p><a href="/en/letters/get-mad-at-where-you-are-in-life-to-get-ahead-of-99-of-people">查看英文存档</a> · <a href="/letters/">返回全部文章</a></p>',172))])}const P=r(d,[["render",m]]);export{g as __pageData,P as default};
